"""Preserve the dated sponsor/release handoff when original report generators run.

No source records, scientific results, portfolio outputs or credentials are changed.
"""
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1]
DOC=ROOT/'docs'

def update(path, fn):
    if path.exists():path.write_text(fn(path.read_text(encoding='utf-8')).strip()+'\n',encoding='utf-8')
def section(text, heading, body):return text.split('\n'+heading)[0].rstrip()+'\n\n'+heading+'\n\n'+body.strip()+'\n'
link='Current November 8 deployment, Cloud development trust, API/benchmark evidence and remaining checks are recorded in [Sponsor evidence](SPONSOR_EVIDENCE.md) and [release audit](SPONSOR_RELEASE_AUDIT.md). Earlier pass-specific statements below retain their historical scope.'
notice='> '+link+'\n\n'
for name in ['VALIDATION.md','GEMINI_SETUP.md','CLEANUP_AND_RELEASE_AUDIT.md','COMPREHENSIVE_SCIENTIFIC_REPORT.md']:
    def add(text):
        if notice in text:return text
        first,rest=text.split('\n',1);return first+'\n\n'+notice+rest.lstrip()
    update(DOC/name,add)

update(ROOT/'README.md',lambda t:t.replace('The project has not been deployed; no GoDaddy or hosting credentials were accessed. The walkthrough is a script, not a recorded video. Publish using your hosting account and complete a desktop/mobile/private-window check before submitting.',
    'The core release is deployed at **https://gilded-ace-decision-room.vercel.app**; the owner confirms the immutable deployment opens on cellular HTTPS. Production Gemini remains unverified pending a trusted-HTTPS POST. Tiger Cloud development import/reconciliation/API/benchmarks passed under an explicitly authorized provisional CA; the hourly feature stays separate from the core production release. Domain actions are on hold with the owner. See [sponsor evidence](docs/SPONSOR_EVIDENCE.md), [hourly setup](docs/TIGER_DATA_SETUP.md), [release audit](docs/SPONSOR_RELEASE_AUDIT.md) and [Devpost checklist](docs/DEVPOST_CHECKLIST.md). The walkthrough remains a script, not a recorded video.'))
update(ROOT/'README.md',lambda t:section(t,'## Hourly operations',
    'The new explorer queries a server-only, read-only Tiger Cloud endpoint for historical heatmaps, weekday/weekend and machine comparisons, and low/high-disruption maintenance templates. It preserves global month/zone/bank filters and Help return, labels missing support and service failures honestly, and never changes the financial portfolio. `npm run start:local` loads the generated ignored `.env.tiger-reader.local` in the API process alongside `.env.local`. No secret belongs in VITE_*. See [setup and measurements](docs/TIGER_DATA_SETUP.md).'))
update(DOC/'DEPLOYMENT.md',lambda t:t.replace('No CLI login, publication or DNS change has been performed by this task. The exact host URL and DNS destination are account/project-specific and cannot be supplied before that project exists.',
    'Current core production alias: https://gilded-ace-decision-room.vercel.app (Vercel READY; owner confirms the immutable URL on cellular). Correct repository and master production branch are connected. GEMINI_API_KEY and GEMINI_MODEL are configured for Preview/Production; live deployed Gemini is still pending. Preview-only hourly variables are DATABASE_URL (reader), TIGER_CA_CERT, TIGER_SCHEMA, TIGER_SERVICE_LABEL and TIGER_TLS_TRUST=provisional-development. No admin database URL or .env file was uploaded. The provisional label is rejected in production. Keep core production unchanged until independently authenticated DB trust and preview checks pass. See SPONSOR_EVIDENCE.md and TIGER_DATA_SETUP.md. Domain actions are on hold; do not purchase, redeem a code or change DNS.'))
update(DOC/'DEPLOYMENT.md',lambda t:section(t,'## Hourly feature release',
    'Deploy the source tree including `api/`, `server/`, `src/` and all three `public/data/*.json` files; the hourly function includes dashboard metadata and uses only the reader connection. SQL migrations/importers remain offline tools, never request-time writes. Production builds require no raw sources or Python. Reader pooling, TLS, limits, exact source binding and setup are documented in TIGER_DATA_SETUP.md. Keep `TIGER_IMPORT_DATABASE_URL` and all local test/admin files out of Vercel. Revalidate the provisional CA independently and rotate the admin password before establishing production trust. New env settings require a new preview build; only promote after trusted HTTPS frontend and both API checks.'))
update(DOC/'GEMINI_SETUP.md',lambda t:t.replace('No public deployment was performed in this task.','The core deployment now reports READY; see SPONSOR_EVIDENCE.md for the exact URL and the still-pending production live POST check.').replace('- Optional future integration: Tiger Data historical hourly explorer, only after live Gemini/demo validation and explicit prioritization. It would serve actual queries against the 2025 hourly table and compare against offline totals. No database was provisioned and no extra sponsor platform was added.',
    '- Tiger Cloud hourly operations is now implemented and development-tested; see TIGER_DATA_SETUP.md. Gemini keeps its existing restricted static-derived evidence tools and does not execute hourly SQL or claim to read those query results. Production Gemini verification remains separate from local or Cloud database success.'))
